def prod_signs(arr):
    if not arr:
        return None

    # Calculate the sum of magnitudes of integers
    magnitude_sum = sum(abs(i) for i in arr)

    # Calculate the product of all signs of each number in the array
    sign_product = 1
    for i in arr:
        if i > 0:
            sign_product *= 1
        elif i < 0:
            sign_product *= -1

    return magnitude_sum * sign_product
