import collections

def histogram(test):
    # Convert the input string to a list of lowercase letters
    test_list = [char for char in test if char.isalpha()]

    # Use collections.Counter to count the occurrences of each letter
    counter = collections.Counter(test_list)

    # Find the letter with the highest occurrence
    max_count = counter.most_common(1)[0][1]

    # Return a dictionary with the letter and its count
    return {char: max_count} if max_count > 0 else {}

# Example usage
print(histogram('a b c'))  # Output: {'a': 1, 'b': 1, 'c': 1}
print(histogram('a b b a'))  # Output: {'a': 2, 'b': 2}
print(histogram('a b c a b'))  # Output: {'a': 2, 'b': 2}
print(histogram('b b b b a'))  # Output: {'b': 4}
print(histogram(''))  # Output: {}
```

