import math

def babylonian_squareroot(x):
    if x < 0:
        return None
    if x == 0:
        return 0
    if x == 1:
        return 1
    if x == 2:
        return 1

    # Initialize the first two values of the sequence
    a = 1
    b = 1

    # Calculate the square root using the Babylonian method
    while True:
        c = a + b
        a = b
        b = c - b
        if c == x:
            return c
        if c < x:
            return c
