def is_majority(arr, target, count):
    left, right = 0, len(arr) - 1
    while left < right:
        mid = (left + right) // 2
        if arr[mid] == target:
            if count == 0:
                return False
            count -= 1
            left = mid
        elif arr[mid] > target:
            right = mid
        else:
            left = mid
    return count == 0

