import math

def comb_sort(arr):
    n = len(arr)
    gap = n
    sorted = False
    while not sorted:
        gap = math.floor(gap / 2)
        for i in range(n - 1 - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
        if gap == 1:
            break
        sorted = True
    return arr
