    integer_part, decimal_part = value.split('.')

    # Check if the value is an integer
    if '.' in value and integer_part == '':
        return int(value)

    # Check if the value is a decimal number
    if '.' in value:
        # If the value is exactly halfway between two integers, return the integer
        if int(value) == int(value) % 1:
            return int(value)
        # Otherwise, round away from zero
        else:
            return int(value) - 1
    else:
        # If the value is a decimal number, return the integer part
        return int(integer_part)
