def closest_integer(value):
    # Split the value into integer and decimal parts
    integer_part, decimal_part = value.split('.')

    # Check if the value is an integer
    if '.' in integer_part:
        integer_part = int(integer_part)

    # Check if the value is a decimal number
    if '.' in decimal_part:
        # If the decimal part is zero, it's a whole number
        if decimal_part == '0':
            return integer_part
        else:
            # If the decimal part is not zero, it's a decimal number
            return int(integer_part) + 1
    else:
        # If the value is a decimal number, round it away from zero
        return int(integer_part) - 1 if integer_part < 0 else int(integer_part) + 1
