def count_samepair(lst1, lst2, lst3):
    # Count the occurrences of each number in the first list
    count1 = {}
    for num in lst1:
        if num in count1:
            count1[num] += 1
        else:
            count1[num] = 1
    
    # Count the occurrences of each number in the second list
    count2 = {}
    for num in lst2:
        if num in count2:
            count2[num] += 1
        else:
            count2[num] = 1
    
    # Count the occurrences of each number in the third list
    count3 = {}
    for num in lst3:
        if num in count3:
            count3[num] += 1
        else:
            count3[num] = 1
    
    # Find the common elements between the three lists
    common_elements = set(lst1) & set(lst2) & set(lst3)
    
    # Count the occurrences of each common element
    count_common = {}
    for element in common_elements:
        if element in count1:
            count_common[element] = count1[element] + count2[element] + count3[element]
        elif element in count2:
            count_common[element] = count2[element] + count3[element]
        elif element in count3:
            count_common[element] = count3[element]
    
    # Return the count of each common element
    return len(common_elements), count_common
