        if num in count2:
            count2[num] += 1
        else:
            count2[num] = 1

    # Count the occurrences of each number in the third list
    count3 = {}
    for num in lst3:
        if num in count3:
            count3[num] += 1
        else:
            count3[num] = 1

    # Find the common elements
    common_elements = set(lst1) & set(lst2) & set(lst3)

    # Count the occurrences of each common element
    count_common = {}
    for element in common_elements:
