        for j in range(1, l2 + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                if dp[i][j] > l1 - i + j:
                    dp[i][j] = l1 - i + j
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[l1][l2]
