def encrypt(s):
    # Create a list of the alphabet
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    # Create a list of the encrypted alphabet
    encrypted_alphabet = []
    # Loop through each character in the input string
    for i in range(len(s)):
        # Loop through each character in the alphabet
        for j in range(len(alphabet)):
            # Check if the current character in the input string matches the current character in the alphabet
            if s[i] == alphabet[j]:
                # Check if the current character in the alphabet matches the current character in the alphabet
                if s[i] == alphabet[j]:
                    # If both conditions are met, add the current character in the alphabet to the encrypted alphabet
                    encrypted_alphabet.append(alphabet[j])
                else:
                    # If the current character in the alphabet is not the current character in the alphabet, add the current character in the alphabet to the encrypted alphabet
                    encrypted_alphabet.append(alphabet[alphabet.index(alphabet[j])])
    # Join the encrypted alphabet into a string and return it
    return ''.join(encrypted_alphabet)
