def do_algebra(operator, operand):
    # Initialize the result with the first operand
    result = operand[0]

    # Iterate over the operator list
    for i in range(len(operator)):
        # Check if the operator is a basic algebra operation
        if operator[i] in ['+', '-', '*', '/', '**']:
            # Get the operands for the current operator
            operand1, operand2 = operator[i], operand[i+1]

            # Evaluate the basic algebra operation
            if operator[i] == '+':
                result += operand1
            elif operator[i] == '-':
                result -= operand1
            elif operator[i] == '*':
                result *= operand1
            elif operator[i] == '/':
                result /= operand1
            else:
                result = result * operand1  # This is a placeholder for the exponentiation operation
    return result
