import math
from typing import List

def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    for i in range(5, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def largest_prime_sum(lst: List[int]) -> int:
    largest_prime = 0
    for num in lst:
        if is_prime(num):
            largest_prime = max(largest_prime, num)
    return largest_prime

def sum_of_digits(lst: List[int]) -> int:
    return sum(int(digit) for digit in lst)

def skjkasdkd(lst: List[int]) -> int:
    return largest_prime_sum(lst) + sum_of_digits(lst)

