def find_last_occurrence(arr, num):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = left + (right - left) // 2
        if arr[mid] == num:
            left = mid
            right = mid
        elif arr[mid] < num:
            left = mid
        else:
            right = mid
    return left
