    while n != 1:
        if n % 2 == 0:
            odd_collatz.append(n // 2)
        else:
            odd_collatz.append(3 * n + 1)
        n = n // 2 if n % 2 == 0 else 3 * n + 1
    odd_collatz.append(1)  # The sequence ends with 1
    odd_collatz.sort()  # The odd numbers are sorted in increasing order
    return odd_collatz
