def modp(n: int, p: int):
    if n < 0 or p < 2:
        raise ValueError("n and p must be non-negative and greater than or equal to 2.")
    if n > p:
        return 1
    result = 1
    while n > 1:
        result = (result * n) % p
        n -= 1
    return result
```

