def is_tree_balanced(root):
    def is_balanced_helper(node):
        if node is None:
            return True, 0
        left_height, left_depth = is_balanced_helper(node.left)
        right_height, right_depth = is_balanced_helper(node.right)

        if left_height > right_height:
            return False, left_depth + 1
        else:
            return True, left_depth + 1 + right_depth + 1

    return is_balanced_helper(root), 0
