def rearange_string(s):
    # Count the frequency of each character
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Check if two adjacent characters are the same
    for i in range(1, len(s) - 1):
        if char_count[s[i]] == char_count[s[i - 1]]:
            return False
    return True
