def shell_sort(arr):
    n = len(arr)
    # 每次找到一个元素，将它与前面的元素进行比较
    for gap in range(n // 2):
        # 从数组的最后一个元素开始，找到一个元素，将它与前面的元素进行比较
        for i in range(n - gap - 1, n):
            # 如果当前元素小于或等于前面的元素，则交换它们
            if arr[i] < arr[i - 1]:
                arr[i], arr[i - 1] = arr[i - 1], arr[i]
    return arr
```

