def tri(n):
    # Initialize the first three numbers of the sequence
    sequence = [1, 3, 2]

    # Generate the rest of the sequence
    for i in range(3, n + 1):
        # Check if the current number is even or odd
        if i % 2 == 0:
            sequence.append(sequence[i - 1] + sequence[i - 2] + sequence[i + 1])
        else:
            sequence.append(sequence[i - 1] + sequence[i - 2] + sequence[i + 1])

