def sort_array(array):
    # Calculate the sum of the first and last index values
    sum_value = array[0] + array[-1]
    # Determine the sorting order based on the sum value
    if sum_value % 2 == 0:
        # If the sum is even, sort the array in ascending order
        return sorted(array)
    else:
        # If the sum is odd, sort the array in descending order
        return sorted(array, reverse=True)
