from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    paren_stack = []
    for char in paren_string:
        if char == '(':
            paren_stack.append(char)
        elif char == ')':
            if len(paren_stack) > 0:
                paren_stack.pop()
            result.append(''.join(map(str, paren_stack)))
            paren_stack = []
    return result
