def answer(a, b):
    # Calculate the greatest common divisor (GCD) of the two numbers
    gcd = a
    for i in range(2, min(a, b) + 1):
        if a % i == 0 and b % i == 0:
            gcd = i
            break
    # Calculate the LCM of the two numbers using the formula LCM(a, b) = (a * b) / GCD(a, b)
    lcm = (a * b) // gcd
    # Check if the LCM is within the given range
    if lcm >= a and lcm <= b:
        return (a, b)
    else:
        return (1, 2)
