import math

def comb_sort(arr):
    n = len(arr)
    gap = n
    sorted = False
    while not sorted:
        gap = math.floor(gap / 2)
        for i in range(1, n - gap):
            if arr[i] < arr[i - 1]:
                arr[i], arr[i - 1] = arr[i - 1], arr[i]
        if gap == 1:
            break
        sorted = True
    return arr
