    for i in range(len(music_string)):
        # Determine the number of beats for the current note
        if music_string[i] == 'o':
            beats[i] = 4
        elif music_string[i] == 'o|':
            beats[i] = 2
        elif music_string[i] == '.|':
            beats[i] = 2
        else:
            beats[i] = 1

    # Return the list of beats for each note
    return beats
